17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
41	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
43	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
44	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
45	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
46	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
47	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Maximum number of owners a single city may hold. A create request whose city already contains
69	     * this many owners is rejected as a conflict.
70	     */
71	    static final int MAX_OWNERS_PER_CITY = 50;
72	
73	    /**
74	     * Maximum number of owners that may be registered on a single day. A create request whose
75	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
76	     */
77	    static final int MAX_OWNERS_PER_DAY = 100;
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    public OwnerRestControllerV1(ClinicService clinicService,
88	                                 OwnerMapper ownerMapper,
89	                                 PetMapper petMapper,
90	                                 VisitMapper visitMapper) {
91	        this.clinicService = clinicService;
92	        this.ownerMapper = ownerMapper;
93	        this.petMapper = petMapper;
94	        this.visitMapper = visitMapper;
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
100	        Collection<Owner> owners;
101	        if (lastName != null) {
102	            owners = this.clinicService.findOwnerByLastName(lastName);
103	        } else {
104	            owners = this.clinicService.findAllOwners();
105	        }
106	        if (owners.isEmpty()) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
115	        Owner owner = this.clinicService.findOwnerById(ownerId);
116	        if (owner == null) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
125	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
126	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
127	        if (!missingFields.isEmpty()) {
128	            throw new MissingOwnerFieldsException(missingFields);
129	        }
130	        HttpHeaders headers = new HttpHeaders();
131	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
132	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
133	            throw new CityCapacityExceededException(owner.getCity());
134	        }
135	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
136	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
137	            throw new DailyOwnerLimitExceededException(registrationDate);
138	        }
139	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
140	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
141	            throw new DuplicateTelephoneException(telephone);
142	        }
143	        Collection<Owner> household =
144	            this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
145	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
146	        if (!household.isEmpty() && !sharesHousehold) {
147	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
148	        }
149	        owner.setTelephone(telephone);
150	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
151	        if (sharesHousehold) {
152	            this.clinicService.joinHousehold(owner, household);
153	        }
154	        this.clinicService.saveOwner(owner);
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        headers.setLocation(UriComponentsBuilder.newInstance()
157	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
158	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
164	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
165	        if (currentOwner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        currentOwner.setAddress(ownerFieldsDto.getAddress());
169	        currentOwner.setCity(ownerFieldsDto.getCity());
170	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
171	        currentOwner.setLastName(ownerFieldsDto.getLastName());
172	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
173	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
174	        this.clinicService.saveOwner(currentOwner);
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Transactional
180	    @Override
181	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        this.clinicService.deleteOwner(owner);
187	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        HttpHeaders headers = new HttpHeaders();
198	        Pet pet = petMapper.toPet(petFieldsDto);
199	        owner.setId(ownerId);
200	        pet.setOwner(owner);
201	        pet.getType().setName(null);
202	        this.clinicService.savePet(pet);
203	        PetDto petDto = petMapper.toPetDto(pet);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
205	            .buildAndExpand(pet.getId()).toUri());
206	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner != null) {
214	            Pet currentPet = this.clinicService.findPetById(petId);
215	            if (currentPet != null) {
216	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
217	                currentPet.setName(petFieldsDto.getName());
218	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
219	                this.clinicService.savePet(currentPet);
220	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
229	        HttpHeaders headers = new HttpHeaders();
230	        Visit visit = visitMapper.toVisit(visitFieldsDto);
231	        Pet pet = new Pet();
232	        pet.setId(petId);
233	        visit.setPet(pet);
234	        this.clinicService.saveVisit(visit);
235	        VisitDto visitDto = visitMapper.toVisitDto(visit);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
237	            .buildAndExpand(visit.getId()).toUri());
238	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
239	    }
240	
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner != null) {
247	            Pet pet = owner.getPet(petId);
248	            if (pet != null) {
249	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
250	            }
251	        }
252	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	    }
254	}
