16	package org.springframework.samples.petclinic.service;
17	
18	import java.time.LocalDate;
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Set;
22	
23	import org.springframework.dao.DataAccessException;
24	import org.springframework.data.domain.Page;
25	import org.springframework.data.domain.Pageable;
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.samples.petclinic.model.Pet;
28	import org.springframework.samples.petclinic.model.PetType;
29	import org.springframework.samples.petclinic.model.Specialty;
30	import org.springframework.samples.petclinic.model.Vet;
31	import org.springframework.samples.petclinic.model.Visit;
32	
33	/**
34	 * Mostly used as a facade so all controllers have a single point of entry
35	 *
36	 * @author Michael Isvy
37	 * @author Vitaliy Fedoriv
38	 */
39	public interface ClinicService {
40	
41		Pet findPetById(int id) throws DataAccessException;
42		Collection<Pet> findAllPets() throws DataAccessException;
43	    Page<Pet> findPets(Pageable pageable) throws DataAccessException;
44		void savePet(Pet pet) throws DataAccessException;
45		void deletePet(Pet pet) throws DataAccessException;
46	
47		Collection<Visit> findVisitsByPetId(int petId);
48		Visit findVisitById(int visitId) throws DataAccessException;
49		Collection<Visit> findAllVisits() throws DataAccessException;
50		void saveVisit(Visit visit) throws DataAccessException;
51		void deleteVisit(Visit visit) throws DataAccessException;
52		Vet findVetById(int id) throws DataAccessException;
53		Collection<Vet> findVets() throws DataAccessException;
54		Collection<Vet> findAllVets() throws DataAccessException;
55		void saveVet(Vet vet) throws DataAccessException;
56		void deleteVet(Vet vet) throws DataAccessException;
57		Owner findOwnerById(int id) throws DataAccessException;
58		Collection<Owner> findAllOwners() throws DataAccessException;
59		Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException;
60		void saveOwner(Owner owner) throws DataAccessException;
61		void deleteOwner(Owner owner) throws DataAccessException;
62		Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException;
63		Collection<Owner> findOwnerByTelephone(String telephone) throws DataAccessException;
64	
65		/**
66		 * Count the number of owners located in the given city.
67		 *
68		 * @param city the city to match
69		 * @return the number of persisted owners in that city
70		 */
71		long countOwnersByCity(String city) throws DataAccessException;
72	
73		/**
74		 * Count the number of owners registered on the given date.
75		 *
76		 * @param registrationDate the registration date to match
77		 * @return the number of persisted owners whose registration date equals the given date
78		 */
79		long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException;
80	
81		/**
82		 * Retrieve the owners that belong to the same household as the given last name and address, i.e.
83		 * whose last name and address both match when compared case-insensitively with collapsed
84		 * whitespace.
85		 *
86		 * @param lastName the last name to match
87		 * @param address the address to match
88		 * @return a <code>Collection</code> of matching <code>Owner</code>s (empty if none)
89		 */
90		Collection<Owner> findOwnersInHousehold(String lastName, String address) throws DataAccessException;
91	
92		/**
93		 * Assign the given owner and every existing member of its household the same stable
94		 * {@code householdId}, persisting the change for any member that does not yet carry it. Used when
95		 * an owner is knowingly created into a shared household.
96		 *
97		 * @param owner the new owner joining the household
98		 * @param existingMembers the owners already in the household (may be empty)
99		 * @return the shared household identifier assigned to the owner
100		 */
