16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Derives the stable identifier shared by owners who belong to the same household, i.e. who share a
24	 * last name and address (compared case-insensitively with collapsed whitespace). Because the
25	 * identifier is a deterministic digest of that normalized pair, every member of a household computes
26	 * the same value, and it never changes as members join or leave.
27	 */
28	public final class HouseholdIdGenerator {
29	
30	    /** Number of leading hex characters of the digest kept as the identifier. */
31	    private static final int LENGTH = 16;
32	
33	    private HouseholdIdGenerator() {
34	    }
35	
36	    /**
37	     * Produce the household identifier for the given last name and address.
38	     *
39	     * @param lastName the household's last name
40	     * @param address the household's address
41	     * @return a stable, non-blank identifier shared by every owner in the household
42	     */
43	    public static String generate(String lastName, String address) {
44	        String key = TextNormalizer.normalizeForComparison(lastName) + '\n'
45	            + TextNormalizer.normalizeForComparison(address);
46	        try {
47	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
48	            StringBuilder hex = new StringBuilder(LENGTH);
49	            for (int i = 0; hex.length() < LENGTH; i++) {
50	                hex.append(String.format("%02X", digest[i]));
51	            }
52	            return hex.substring(0, LENGTH);
53	        } catch (NoSuchAlgorithmException ex) {
54	            // SHA-256 is required to be available on every JVM, so this cannot happen.
55	            throw new IllegalStateException("SHA-256 algorithm not available", ex);
56	        }
57	    }
58	}
