112	            this.em.persist(owner);
113	        } else {
114	            this.em.merge(owner);
115	        }
116	
117	    }
118	
119		@SuppressWarnings("unchecked")
120		@Override
121		public Collection<Owner> findAll() throws DataAccessException {
122			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
123	        return query.getResultList();
124		}
125	
126	    @SuppressWarnings("unchecked")
127	    @Override
128	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
129	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
130	        query.setFirstResult((int) pageable.getOffset());
131	        query.setMaxResults(pageable.getPageSize());
132	        List<Owner> owners = query.getResultList();
133	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
134	        long total = (long) countQuery.getSingleResult();
135	        return new PageImpl<>(owners, pageable, total);
136	    }
137	
138		@Override
139		public long count() throws DataAccessException {
140			Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
141			return (long) countQuery.getSingleResult();
142		}
143	
144		@Override
145		public long countByCity(String city) throws DataAccessException {
146			Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.city = :city");
147			countQuery.setParameter("city", city);
148			return (long) countQuery.getSingleResult();
149		}
150	
151		@Override
152		public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
153			Query countQuery = this.em.createQuery(
154				"SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
155			countQuery.setParameter("registrationDate", registrationDate);
156			return (long) countQuery.getSingleResult();
157		}
158	
159		@Override
160		public void delete(Owner owner) throws DataAccessException {
161			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
162		}
